#include <stdio.h>
#include <string.h>

int is_blank(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

// Печатает символы [from, to) без пробелов по краям, группы пробелов — одним пробелом.
void print_squeezed(const char *from, const char *to) {
    while (from < to && is_blank(*from)) {
        from++;
    }
    while (to > from && is_blank(to[-1])) {
        to--;
    }
    int gap = 0;
    for (const char *p = from; p < to; p++) {
        if (is_blank(*p)) {
            gap = 1;
            continue;
        }
        if (gap) {
            putchar(' ');
            gap = 0;
        }
        putchar(*p);
    }
}

int only_blanks(const char *from, const char *to) {
    for (const char *p = from; p < to; p++) {
        if (!is_blank(*p)) {
            return 0;
        }
    }
    return 1;
}

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        const char *open = strchr(line, '(');
        const char *close = strchr(line, ')');
        if (open == NULL || close == NULL) {
            continue;
        }
        print_squeezed(line, open);
        putchar('(');
        if (only_blanks(open + 1, close)) {
            printf("void");
        } else {
            const char *start = open + 1;
            for (;;) {
                const char *comma = memchr(start, ',', (size_t)(close - start));
                const char *end = comma != NULL ? comma : close;
                print_squeezed(start, end);
                if (comma == NULL) {
                    break;
                }
                printf(", ");
                start = comma + 1;
            }
        }
        printf(");\n");
    }
    return 0;
}

