#include <ctype.h>
#include <stdio.h>

long long parse_expr(void);
long long parse_term(void);
long long parse_factor(void);

const char *pos;
int division_by_zero;

void skip_spaces(void) {
    while (*pos == ' ' || *pos == '\t') {
        pos++;
    }
}

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        pos = line;
        division_by_zero = 0;
        long long value = parse_expr();
        if (division_by_zero) {
            printf("деление на ноль\n");
        } else {
            printf("%lld\n", value);
        }
    }
    return 0;
}

long long parse_expr(void) {
    long long value = parse_term();
    for (;;) {
        skip_spaces();
        char op = *pos;
        if (op != '+' && op != '-') {
            return value;
        }
        pos++;
        long long right = parse_term();
        value = op == '+' ? value + right : value - right;
    }
}

long long parse_term(void) {
    long long value = parse_factor();
    for (;;) {
        skip_spaces();
        char op = *pos;
        if (op != '*' && op != '/' && op != '%') {
            return value;
        }
        pos++;
        long long right = parse_factor();
        if (op == '*') {
            value *= right;
        } else if (right == 0) {
            division_by_zero = 1;
        } else if (op == '/') {
            value /= right;
        } else {
            value %= right;
        }
    }
}

long long parse_factor(void) {
    skip_spaces();
    if (*pos == '-') {
        pos++;
        return -parse_factor();
    }
    if (*pos == '(') {
        pos++;
        long long value = parse_expr();
        skip_spaces();
        pos++;                      // закрывающая скобка
        return value;
    }
    long long value = 0;
    while (isdigit((unsigned char)*pos)) {
        value = value * 10 + (*pos - '0');
        pos++;
    }
    return value;
}

